//! Experimental all-hit extraction from AlphaNovo-compiled exact and anchor-bag queries.
//! Mass alternatives are generated by AlphaNovo, not redefined in this engine.
use aho_corasick::{AhoCorasickBuilder, AhoCorasickKind};
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
use std::collections::{BTreeMap, HashMap};
use std::fs::File;
use std::io::{self, BufRead, BufReader, BufWriter, Write};

#[derive(Deserialize)]
struct Element {
    letters: String,
    unordered: bool,
}
#[derive(Deserialize)]
struct Input {
    seed: String,
    #[serde(default)]
    offset: usize,
    #[serde(default)]
    elements: Vec<Element>,
    query: usize,
    route: u16,
    lookup: bool,
}
struct Pattern {
    offset: usize,
    elements: Vec<(Vec<u8>, bool)>,
    query: usize,
    route: u16,
    lookup: bool,
}
#[derive(Serialize)]
struct Output<'a> {
    header: &'a str,
    sequence: &'a str,
    lookup_routes: u16,
    evidence: Vec<(usize, u16)>,
}
fn norm(s: &str) -> Vec<u8> {
    s.bytes()
        .map(|b| {
            if b.eq_ignore_ascii_case(&b'I') {
                b'L'
            } else {
                b.to_ascii_uppercase()
            }
        })
        .collect()
}
fn emit(
    header: &str,
    sequence: &str,
    auto: &aho_corasick::AhoCorasick,
    by_seed: &[Vec<usize>],
    patterns: &[Pattern],
    out: &mut impl Write,
) -> io::Result<(u64, u64)> {
    let seq = norm(sequence);
    let mut evidence = BTreeMap::<usize, u16>::new();
    let mut lookup_routes = 0;
    for hit in auto.find_overlapping_iter(&seq) {
        for &idx in &by_seed[hit.pattern().as_usize()] {
            let p = &patterns[idx];
            if hit.start() < p.offset {
                continue;
            }
            let mut pos = hit.start() - p.offset;
            let mut good = true;
            for (letters, unordered) in &p.elements {
                let end = pos + letters.len();
                if end > seq.len() {
                    good = false;
                    break;
                }
                if *unordered {
                    let mut observed = seq[pos..end].to_vec();
                    observed.sort_unstable();
                    if observed != *letters {
                        good = false;
                        break;
                    }
                } else if seq[pos..end] != *letters {
                    good = false;
                    break;
                }
                pos = end;
            }
            if good {
                *evidence.entry(p.query).or_default() |= p.route;
                if p.lookup {
                    lookup_routes |= p.route;
                }
            }
        }
    }
    if lookup_routes == 0 {
        return Ok((0, 0));
    }
    let n = evidence.len() as u64;
    serde_json::to_writer(
        &mut *out,
        &Output {
            header,
            sequence,
            lookup_routes,
            evidence: evidence.into_iter().collect(),
        },
    )?;
    out.write_all(b"\n")?;
    Ok((1, n))
}
fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args: Vec<String> = std::env::args().collect();
    assert_eq!(args.len(), 4, "queries.jsonl reservoir.fasta receipt.json");
    let mut seeds = Vec::<String>::new();
    let mut seed_index = HashMap::<String, usize>::new();
    let mut by_seed = Vec::<Vec<usize>>::new();
    let mut patterns = Vec::<Pattern>::new();
    for line in BufReader::new(File::open(&args[1])?).lines() {
        let p: Input = serde_json::from_str(&line?)?;
        assert!(!p.seed.is_empty());
        let index = *seed_index.entry(p.seed.clone()).or_insert_with(|| {
            seeds.push(p.seed);
            by_seed.push(Vec::new());
            seeds.len() - 1
        });
        by_seed[index].push(patterns.len());
        let elements = p
            .elements
            .into_iter()
            .map(|e| {
                let mut letters = norm(&e.letters);
                if e.unordered {
                    letters.sort_unstable();
                }
                (letters, e.unordered)
            })
            .collect();
        patterns.push(Pattern {
            offset: p.offset,
            elements,
            query: p.query,
            route: p.route,
            lookup: p.lookup,
        });
    }
    drop(seed_index);
    let auto = AhoCorasickBuilder::new()
        .kind(Some(AhoCorasickKind::ContiguousNFA))
        .build(&seeds)?;
    let seed_count = seeds.len();
    drop(seeds);
    let mut reader = BufReader::with_capacity(8 * 1024 * 1024, File::open(&args[2])?);
    let mut out = BufWriter::with_capacity(1024 * 1024, io::stdout().lock());
    let mut line = String::new();
    let mut header = String::new();
    let mut sequence = String::new();
    let mut hasher = Sha256::new();
    let (mut records, mut residues, mut parents, mut edges) = (0_u64, 0_u64, 0_u64, 0_u64);
    loop {
        line.clear();
        if reader.read_line(&mut line)? == 0 {
            break;
        }
        hasher.update(line.as_bytes());
        let value = line.trim();
        if value.is_empty() {
            continue;
        }
        if let Some(h) = value.strip_prefix('>') {
            if !header.is_empty() {
                assert!(!sequence.is_empty());
                let (n, e) = emit(&header, &sequence, &auto, &by_seed, &patterns, &mut out)?;
                records += 1;
                residues += sequence.len() as u64;
                parents += n;
                edges += e;
            }
            assert!(!h.trim().is_empty());
            header = h.to_owned();
            sequence.clear();
        } else {
            assert!(!header.is_empty());
            assert!(value.bytes().all(|b| b.is_ascii_alphabetic() || b == b'*'));
            sequence.push_str(&value.to_ascii_uppercase());
        }
    }
    if !header.is_empty() {
        assert!(!sequence.is_empty());
        let (n, e) = emit(&header, &sequence, &auto, &by_seed, &patterns, &mut out)?;
        records += 1;
        residues += sequence.len() as u64;
        parents += n;
        edges += e;
    }
    out.flush()?;
    assert!(records > 0);
    let receipt = serde_json::json!({"status":"FULL_SCAN_COMPLETE", "patterns":patterns.len(), "seeds":seed_count,
        "reservoir_records":records, "reservoir_residues":residues, "reservoir_sha256":hasher.finalize().iter().map(|b| format!("{b:02x}")).collect::<String>(),
        "candidate_proteins":parents, "evidence_edges":edges});
    serde_json::to_writer_pretty(File::create(&args[3])?, &receipt)?;
    eprintln!("{receipt}");
    Ok(())
}
